#!/usr/bin/env node
// Regenerates test/fixtures/atem-vectors.json from a checkout of Sofie's atem-connection (MIT):
//   node test/fixtures/build-atem-vectors.js <path-to-atem-connection>
// It takes up to three LibAtem-generated vectors per command from src/commands/__tests__/libatem-data.json and converts
// the LibAtem (float) values to the switcher's integer units with the same scalings as atem-connection's converters.
'use strict';
const fs = require('fs'); const path = require('path');
const src = process.argv[2]; if (!src) { console.error('usage: build-atem-vectors.js <atem-connection dir>'); process.exit(1); }
const data = JSON.parse(fs.readFileSync(path.join(src, 'src/commands/__tests__/libatem-data.json'), 'utf8'));
const lf = (s) => s[0].toLowerCase() + s.slice(1);
const r = (k) => (v) => Math.round(v * k);
const MASK = { maskTop: r(1000), maskBottom: r(1000), maskLeft: r(1000), maskRight: r(1000) };
const DVE = { ...MASK, sizeX: r(1000), sizeY: r(1000), positionX: r(1000), positionY: r(1000), rotation: r(10), borderHue: r(10), borderSaturation: r(10), borderLuma: r(10), borderInnerWidth: r(100), borderOuterWidth: r(100), lightSourceDirection: r(10) };
const BORDER = { hue: r(10), saturation: r(10), luma: r(10), innerWidth: r(100), outerWidth: r(100), lightSourceDirection: r(10), lightSourceAltitude: r(1) };
const BOX = { positionX: r(100), positionY: r(100), size: r(1000), cropTop: r(1000), cropBottom: r(1000), cropLeft: r(1000), cropRight: r(1000) };
const PAT = { size: r(100), symmetry: r(100), softness: r(100), xPosition: r(10000), yPosition: r(10000) };
const CK = { hue: r(10), gain: r(10), ySuppress: r(10), lift: r(10) };
const LUMA = { clip: r(10), gain: r(10) };
const FL = { gain: r(100), balance: r(100), equalizerGain: r(100), makeUpGain: r(100), faderGain: r(100), stereoSimulation: r(100), inputMasterGain: r(100), inputTalkbackGain: r(100), inputSidetoneGain: r(100) };
const db = (v) => (v <= -60 ? 0 : Math.min(65535, Math.floor(10 ** (v / 20) * 32768)));
const CLA = { gain: db, programOutGain: db, talkbackGain: db, sidetoneGain: db, balance: (v) => Math.round(v * 200), dimLevel: r(100) };
const SPEC = {
  CMvI: {}, MvIn: {}, MvPr: {}, _MvC: {}, _SSC: {}, _AMC: {}, _FAC: {},
  CKTp: {}, CKeF: {}, CKeC: {}, CKMs: MASK, KeBP: MASK, CKLm: LUMA, KeLm: LUMA, CKCk: CK, KeCk: CK, CKPt: PAT, KePt: PAT, CKDV: DVE, KeDV: DVE, KeFS: {}, SFKF: {}, RFlK: {},
  CDsF: {}, CDsC: {}, CDsG: LUMA, CDsM: MASK, CDsR: {}, DskB: {}, DskP: { ...LUMA, ...MASK },
  CSBP: BOX, SSBP: BOX, CSSc: { artClip: r(10), artGain: r(10) }, SSrc: { artClip: r(10), artGain: r(10) }, CSBd: BORDER, SSBd: BORDER,
  CAMI: CLA, AMIP: {}, CAMM: CLA, AMMO: {}, CAMm: CLA, AMmO: {}, CAMH: CLA, AMHP: {}, AMPP: {},
  CFSP: FL, FASP: FL, FAIP: {}, CFMP: FL, FAMP: FL, CFMH: FL, FMHP: FL, AROC: {}, AROP: {}, ARSP: {},
};
const MAXV = 0x20020; // V9.6
const out = [];
for (const [name, conv] of Object.entries(SPEC)) {
  const vs = data.filter((x) => x.name === name && x.firstVersion <= MAXV);
  const best = Math.max(...vs.map((x) => x.firstVersion));
  for (const v of vs.filter((x) => x.firstVersion === best).slice(0, 3)) {
    const c = {}; for (const [k, val] of Object.entries(v.command)) { const n = lf(k); c[n] = conv[n] && typeof val === 'number' ? conv[n](val) : val; }
    if (name === 'AMIP' || name === 'AMMO' || name === 'AMmO' || name === 'AMHP') c._dbFields = true; // getters compare as dB / percent
    out.push({ name, version: v.firstVersion, bytes: v.bytes, c });
  }
}
const note = 'Byte vectors generated by LibAtem, taken from Sofie atem-connection (MIT) src/commands/__tests__/libatem-data.json; values converted to switcher integer units by test/fixtures/build-atem-vectors.js';
fs.writeFileSync(path.join(__dirname, 'atem-vectors.json'), JSON.stringify({ note, vectors: out }, null, 0).replace(/\},\{"name"/g, '},\n{"name"') + '\n');
console.log('wrote', out.length, 'vectors');
